CREATE TEMPORARY TABLE family_delete_2370707dfafc07d008b8fce1cfbf1fe6 AS SELECT d."_dlt_id" FROM "raw"."family" as d WHERE EXISTS (SELECT 1 FROM "raw_staging"."family" as s WHERE d."id" = s."id")
DELETE FROM "raw"."family__kids"             WHERE "_dlt_root_id" IN (                 SELECT * FROM family_delete_2370707dfafc07d008b8fce1cfbf1fe6             );         
DELETE FROM "raw"."family"             WHERE "_dlt_id" IN (                 SELECT * FROM family_delete_2370707dfafc07d008b8fce1cfbf1fe6             );         
CREATE TEMPORARY TABLE family_insert_260f1b3d5f2ffe9630f3681d17360048 AS                  SELECT "_dlt_id"                     FROM (                         SELECT ROW_NUMBER() OVER (partition BY "id" ORDER BY (SELECT NULL)) AS _dlt_dedup_rn, "_dlt_id"                         FROM "raw_staging"."family"                     ) AS _dlt_dedup_numbered WHERE _dlt_dedup_rn = 1 AND (1 = 1)          
INSERT INTO "raw"."family"("id", "updated", "_dlt_load_id", "_dlt_id") SELECT "id", "updated", "_dlt_load_id", "_dlt_id" FROM "raw_staging"."family" WHERE "_dlt_id" IN (SELECT * FROM family_insert_260f1b3d5f2ffe9630f3681d17360048)
INSERT INTO "raw"."family__kids"("a", "_dlt_root_id", "_dlt_parent_id", "_dlt_list_idx", "_dlt_id")                  SELECT "a", "_dlt_root_id", "_dlt_parent_id", "_dlt_list_idx", "_dlt_id"                     FROM (                         SELECT ROW_NUMBER() OVER (partition BY "_dlt_id" ORDER BY (SELECT NULL)) AS _dlt_dedup_rn, "a", "_dlt_root_id", "_dlt_parent_id", "_dlt_list_idx", "_dlt_id"                         FROM "raw_staging"."family__kids"                     ) AS _dlt_dedup_numbered WHERE _dlt_dedup_rn = 1 AND ("_dlt_root_id" IN (SELECT * FROM family_insert_260f1b3d5f2ffe9630f3681d17360048))          